## Why This Is Asked
Tests ability to bridge Go and C with callbacks, manage lifetimes, and avoid unsafe pointer passes.

## Key Concepts
- CGO callbacks and trampolines
- cgo.Handle for Go values across C boundaries
- Memory ownership and handle release
- Thread-safety when called from C across Go threads

## Complete Implementation

**C Header (stream.h):**
```c
typedef void (*cb_t)(int, void*);
void register_stream(cb_t cb, void* user);
void trampoline(int value, void* handle_ptr);
void unregister_stream(void);
```

**C Trampoline (stream.c):**
```c
#include "stream.h"
#include <stdint.h>

void trampoline(int value, void* handle_ptr) {
    uintptr_t handle = (uintptr_t)handle_ptr;
    // This calls back into Go via cgo.Handle
    extern void go_callback(int value, uintptr_t handle);
    go_callback(value, handle);
}
```

**Go Binding:**
```go
/*
#cgo LDFLAGS: -L. -lstream
#include "stream.h"
*/
import "C"
import "unsafe"

var activeStreams = make(map[uintptr]chan int)
var streamsMutex sync.RWMutex

//export go_callback
func go_callback(value C.int, handlePtr C.uintptr_t) {
    handle := uintptr(handlePtr)
    streamsMutex.RLock()
    if ch, exists := activeStreams[handle]; exists {
        select {
        case ch <- int(value):
        default:
            // Channel full, drop value
        }
    }
    streamsMutex.RUnlock()
}

func StartStream() (<-chan int, func()) {
    ch := make(chan int, 100)

    // Create wrapper function and handle
    done := make(chan struct{})
    handle := C.uintptr_t(C.NewHandle(done))

    streamsMutex.Lock()
    activeStreams[uintptr(handle)] = ch
    streamsMutex.Unlock()

    // Register with C trampoline
    C.register_stream((*[0]byte)(C.trampoline), unsafe.Pointer(handle))

    // Cleanup function
    cleanup := func() {
        C.unregister_stream()
        C.Delete(C.Handle(handle))

        streamsMutex.Lock()
        delete(activeStreams, uintptr(handle))
        streamsMutex.Unlock()

        close(ch)
    }

    return ch, cleanup
}

// Usage example:
func consumeStreams() {
    stream1, stop1 := StartStream()
    stream2, stop2 := StartStream()

    go func() {
        for val := range stream1 {
            fmt.Printf("Stream 1: %d\n", val)
        }
    }()

    go func() {
        for val := range stream2 {
            fmt.Printf("Stream 2: %d\n", val)
        }
    }()

    // Stop after some time
    time.Sleep(5 * time.Second)
    stop1()
    stop2()
}
```

## Follow-up Questions
- How would you handle panics in the Go callback invoked from C?
- What are performance implications of per-call handles vs static wrappers?
- How can you prevent memory leaks if the C side never calls unregister?

## Why This Is Asked
This question tests safe interop for TLV parsing with proper memory ownership and concurrent batching.

## Key Concepts
- CGO memory ownership across language boundaries
- TLV parsing robustness and error handling
- Thread-safety and worker pools
- Zero-copy vs copy trade-offs
- Error propagation from C to Go

## Code Example
```c
// tlv_parser.h
typedef struct TLV {
    uint16_t type;
    uint16_t len;
    const uint8_t* value;
} TLV;

char* parse_tlvs(const uint8_t* data, size_t length);
void free_json(char* json);
```

```c
// tlv_parser.c
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include "tlv_parser.h"

static uint8_t rolling_checksum(const uint8_t* data, size_t len) {
    uint8_t sum = 0;
    for (size_t i = 0; i < len; i++) {
        sum = (sum << 1) | (sum >> 7);
        sum ^= data[i];
    }
    return sum;
}

char* parse_tlvs(const uint8_t* data, size_t length) {
    if (!data || length < 4) return NULL;

    size_t offset = 0;
    size_t capacity = 256;
    char* json = malloc(capacity);
    if (!json) return NULL;

    int pos = snprintf(json, capacity, "[{\n");

    while (offset + 4 <= length) {
        uint16_t tlv_type = (data[offset] << 8) | data[offset + 1];
        uint16_t tlv_len = (data[offset + 2] << 8) | data[offset + 3];

        if (offset + 4 + tlv_len > length) break;

        uint8_t checksum = rolling_checksum(data + offset + 4, tlv_len);

        char entry[128];
        int len = snprintf(entry, sizeof(entry),
            "  {\"type\": %d, \"length\": %d, \"checksum\": %d}%s\n",
            tlv_type, tlv_len, checksum,
            (offset + 4 + tlv_len < length) ? "," : "");

        if (pos + len >= (int)capacity) {
            capacity *= 2;
            json = realloc(json, capacity);
        }
        pos += snprintf(json + pos, capacity - pos, "%s", entry);
        offset += 4 + tlv_len;
    }

    snprintf(json + pos, capacity - pos, "}]");
    return json;
}

void free_json(char* json) {
    free(json);
}
```

```go
// tlvbinding.go
package main

// #include "tlv_parser.h"
import "C"
import (
    "errors"
    "runtime"
    "unsafe"
)

func DecodeTLVs(buf []byte) (string, error) {
    if len(buf) == 0 {
        return "", errors.New("empty buffer")
    }

    cdata := (*C.uint8_t)(unsafe.Pointer(&buf[0]))
    clength := C.size_t(len(buf))

    cjson := C.parse_tlvs(cdata, clength)
    if cjson == nil {
        return "", errors.New("C parsing failed")
    }

    defer C.free_json(cjson)

    result := C.GoString(cjson)
    return result, nil
}
